{
  "story": "Recursive calls push new activation frames onto the call stack, allocating local variables. Reaching the base case halts descent, and returning pops frames one by one while computing results.",
  "aha": {
    "stateId": "pop1",
    "observation": "Base case reached, top frame starts popping and returning values downward."
  },
  "layout": {
    "preset": "stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "completedBefore": "inputs.stepIndex"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Stack Step",
      "options": ["push3", "push2", "push1", "base", "pop1", "pop2", "pop3"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset Stack",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Recursion Depth 3",
        "regions": [
          {
            "id": "frame3",
            "label": "Frame f(3)",
            "kind": "stack-frame",
            "values": ["n=3", "calc=3*f(2)"]
          },
          {
            "id": "frame2",
            "label": "Frame f(2)",
            "kind": "stack-frame",
            "values": ["n=2", "calc=2*f(1)"]
          },
          {
            "id": "frame1",
            "label": "Frame f(1)",
            "kind": "stack-frame",
            "values": ["n=1", "calc=1*f(0)"]
          },
          {
            "id": "frame0",
            "label": "Base f(0)",
            "kind": "stack-frame",
            "values": ["n=0", "return 1"]
          }
        ],
        "states": [
          {
            "id": "push3",
            "label": "Push f(3)",
            "short": "f(3)",
            "sentence": "Initial call pushes f(3) onto the stack.",
            "why": "Allocates space for n=3.",
            "active": ["frame3"],
            "calloutRegion": "frame3",
            "readouts": [
              {"id": "depth", "label": "Stack Depth", "value": "1"},
              {"id": "top", "label": "Top Frame", "value": "f(3)"}
            ]
          },
          {
            "id": "push2",
            "label": "Push f(2)",
            "short": "f(2)",
            "sentence": "f(3) calls f(2), pushing a new frame.",
            "why": "Allocates space for n=2.",
            "active": ["frame3", "frame2"],
            "calloutRegion": "frame2",
            "readouts": [
              {"id": "depth", "label": "Stack Depth", "value": "2"},
              {"id": "top", "label": "Top Frame", "value": "f(2)"}
            ]
          },
          {
            "id": "push1",
            "label": "Push f(1)",
            "short": "f(1)",
            "sentence": "f(2) calls f(1), pushing another frame.",
            "why": "Allocates space for n=1.",
            "active": ["frame3", "frame2", "frame1"],
            "calloutRegion": "frame1",
            "readouts": [
              {"id": "depth", "label": "Stack Depth", "value": "3"},
              {"id": "top", "label": "Top Frame", "value": "f(1)"}
            ]
          },
          {
            "id": "base",
            "label": "Base Case",
            "short": "f(0)",
            "sentence": "f(1) calls f(0), hitting the base case.",
            "why": "No more recursive calls; returns 1.",
            "active": ["frame3", "frame2", "frame1", "frame0"],
            "calloutRegion": "frame0",
            "readouts": [
              {"id": "depth", "label": "Stack Depth", "value": "4"},
              {"id": "top", "label": "Top Frame", "value": "f(0)"}
            ]
          },
          {
            "id": "pop1",
            "label": "Pop f(0)",
            "short": "Pop 0",
            "sentence": "Base case returns 1, popping f(0) off.",
            "why": "Unwinds frame and computes 1*1.",
            "active": ["frame3", "frame2", "frame1"],
            "calloutRegion": "frame1",
            "readouts": [
              {"id": "depth", "label": "Stack Depth", "value": "3"},
              {"id": "top", "label": "Top Frame", "value": "f(1)"}
            ]
          },
          {
            "id": "pop2",
            "label": "Pop f(1)",
            "short": "Pop 1",
            "sentence": "f(1) completes and pops off the stack.",
            "why": "Returns 1 to f(2), computing 2*1.",
            "active": ["frame3", "frame2"],
            "calloutRegion": "frame2",
            "readouts": [
              {"id": "depth", "label": "Stack Depth", "value": "2"},
              {"id": "top", "label": "Top Frame", "value": "f(2)"}
            ]
          },
          {
            "id": "pop3",
            "label": "Pop f(2)",
            "short": "Pop 2",
            "sentence": "f(2) completes and pops off the stack.",
            "why": "Returns 2 to f(3), computing 3*2.",
            "active": ["frame3"],
            "calloutRegion": "frame3",
            "readouts": [
              {"id": "depth", "label": "Stack Depth", "value": "1"},
              {"id": "top", "label": "Top Frame", "value": "f(3)"}
            ]
          }
        ]
      }
    ]
  }
}
